FALLBACK_POLICY_BY_POST_ID.update({
    "11918698": (
        "深圳市市场监督管理局深圳标准领域专项资金资助奖励操作规程",
        "深圳市市场监督管理局修订深圳标准领域专项资金资助奖励操作规程，专项资金用于支持标准研制能力提升、企业标准化能力建设和培育、深圳标准认证推广建设、标准化推广和教育、标准化技术和服务支撑机构培育等资助项目，以及深圳市科学技术奖标准奖、中国标准创新贡献奖配套奖励、国际标准化人才奖励、国内标准化人才奖励等资金奖励。资助是对已实施完毕且符合资助条件并取得标准化成果的项目给予事后无偿资助，奖励是对符合奖励条件、获得相关表彰或担任重要职务的项目给予资金奖励。申请主体应是在深圳实际经营的企事业单位、社会组织或其他机构，标准业务归口深圳市管理或统计，且不得严重失信、不得同一项目多头或重复申请市财政性资金。标准研制方面，主导国际标准制定按项目给予不超过100万元资助，主导国际标准修订不超过40万元，参与国际标准制定不超过50万元，参与国际标准修订不超过20万元；主导国家标准制定不超过50万元，参与国家标准制定不超过25万元；主导行业标准制定不超过30万元，参与行业标准制定不超过15万元；主导深圳市地方标准制定不超过20万元。深圳市团体标准培优项目每项资助不超过10万元，年度资助项目总数不超过30项，同一单位资助项目不超过5项。标准试点或示范项目按国家级、省级分别给予50万元、30万元资助；深圳标准创新基地一次性给予50万元资助；深圳市研发与标准化同步企业A级给予30万元、B级给予18万元资助；企业标准领跑者项目按项目给予3万元资助，同一单位每年不超过5个项目；标准创新型企业高级、中级分别给予不超过30万元、15万元一次性资助。深圳标准先进性评价细则制定项目不超过5万元；深圳标准认证获证项目每个不超过10万元，同一单位每年不超过3个项目；深圳标准推广项目按实际支出给予不超过50万元资助，年度不超过5项；深圳标准培训项目按实际支出给予不超过10万元资助，年度不超过15项；深圳标准化教育课程设立项目按项目给予20万元资助。申报资料通常包括申请表、主体资格材料、标准发布公告、标准文本、标准编制说明、提案采纳材料、参会记录、劳动合同、标准平台声明、采用实施证明、检测报告、认证证书、活动方案、工作总结、绩效自评报告、审计资料等。"
    ),
})

