FALLBACK_POLICY_BY_POST_ID.update({
    "20260001": (
        "南山区促进产业高质量发展专项资金--区商务局分项资金外资项目奖励操作规程（2026年度）",
        "为优化辖区经济结构，转变经济增长模式，吸引外商投资企业落户南山区及持续发展，南山区制定外资项目奖励操作规程。政策提出，对上年度实际使用外资不少于1000万美元的外商投资企业，按其年度实际使用外资金额的1%，给予最高1000万元的奖励。本项资助属于核准类项目，采取无偿资助方式和事后补贴，受资助项目无需验收。资助资金安排坚持公平、公开、公正，实行自愿申报、科学决策和绩效评估，受年度资金预算控制。区商务局可视申报情况和预算安排，对资助金额、支持比例和拨付进度等进行统一调整，资助金额以万元为单位按照舍尾法确定。申请单位应是在深圳市南山区依法实际从事经营活动，具有独立承担民事责任能力的外商投资企业，不包括房地产业及未纳入商务部实际使用外资统计口径的金融业及类金融业项目。企业需履行外资等相关数据和信息申报义务，守法经营、诚实守信，有规范健全的财务制度。申请主体须承诺5年内不减少注册资本、不转为内资企业，数据申报地关系不发生变化，未履行承诺的，将按程序收回奖励资金。申请奖励资金的新设和增资项目的实际使用外资金额，是指外方投资者以境外现汇、跨境人民币、利润再投资和资本公积等4种方式实缴或转增企业注册资本，并通过商务部门2025年核查公布的实际使用外资金额。单个企业或项目在2026年度获得该项外资奖励资金金额累计不得超过1000万元，且本项目奖励不与前海合作区同类性质扶持政策叠加享受。被依法依规纳入严重失信主体名单或失信惩戒措施清单的，或提出资助申请后企业数据申报地关系发生变化不再符合申报条件的，不予资助。"
    ),
})


