        "南山区重点科技创新类机构支持计划面向在南山区依法经营，承担或承建市、区重点支持建设重大科技创新类机构项目的企事业单位。重大科技创新类机构项目应符合战略性新兴产业和未来产业发展方向，并以市、区政府签订的协议为准。政策提出，对市、区重点支持建设的科技创新类机构项目，根据相关协议、文件，给予研究开发、场地租金、建设运营等经费资助，每年每机构项目最高资助2500万元。本资助计划资助金额受区科技资金年度总额控制。申报主体为事业单位的，自投经费不设强制性要求；申报主体为企业的，按不超过项目当年总投入的50%给予资助。资助方式采取核准与评审相结合，实行单位申报、材料审核、专家评审、社会公示、政府决策的原则，采取事前资助、事中评估、事后验收的资助方式。对于实施期超过一年的项目，第二年及后续阶段申报时，项目实施内容、考核指标、经费使用计划等无实质性变化的，无需再次评审。"
