def opening_key(text: str) -> str:
    compact = re.sub(r"^[\s　‘’“”\'\"（(【\[]+", "", text or "")
    compact = re.sub(r"[，。！？；：、,.!?;:\s].*$", "", compact[:24])
    return compact[:10]


def vary_article_paragraph_openings(paragraphs: list[str], article_index: int) -> list[str]:
    """Make paragraph starts feel less templated inside one article.

    Handwritten builders sometimes produce good policy detail but still start several
    paragraphs with the same role label or structure. This pass only changes the
    front door of long paragraphs: it rotates short conversational leads, trims
    duplicate prefixes, and leaves brand/CTA wording intact.
    """
    varied: list[str] = []
    local_counts: dict[str, int] = {}
    role_prefix_re = re.compile(
        r"^(财务同事|项目负责人|技术团队|质量负责人|老板|行政同事|市场团队|标准负责人|申报经办人|研发负责人|品牌负责人|运营团队|管理层|资料负责人|合规同事|业务部门)"
        r"(先看这个点|可以这样拆|别漏这个细节|要提前留痕|先把资料排队|可以换个角度看|最好先算一笔账|别只看表面金额|要把证据链拉直|可以先做一次体检|更适合先核口径|要把时间线理清)，?"
    )
    for idx, paragraph in enumerate(paragraphs):
        text = paragraph.strip()
        if idx == 0 or len(text) < 90:
            varied.append(remove_template_section_labels(text) if idx == len(paragraphs) - 1 else text)
            continue
        if idx == len(paragraphs) - 1:
            varied.append(remove_template_section_labels(text))
            continue
        text = role_prefix_re.sub("", text).lstrip("，,。；;：: ")
        text = re.sub(
            r"^(先看对象|为什么值得做|时间和场景要抓住|深圳金赋可以怎么帮|材料不用一口气做完|最后动作|项目边界也要提前排除|费用和翻译是海外项目的关键)[。．]\s*",
            "",
            text,
        )
        key = opening_key(text)
        local_counts[key] = local_counts.get(key, 0) + 1
        should_add_lead = local_counts[key] > 1 or idx % 2 == 0
        if should_add_lead and not text.startswith(tuple(OPENING_MOODS)):
            lead = OPENING_MOODS[(article_index * 7 + idx * 3) % len(OPENING_MOODS)]
            if lead.endswith("是"):
                text = f"{lead}{text}"
            elif lead.endswith("？"):
                text = f"{lead}{text}"
            else:
                text = f"{lead}{text}"
        text = remove_template_section_labels(text)
        varied.append(remove_unbalanced_brackets(cleanup_generated_wording(text)).strip())
    return varied


def enforce_batch_opening_variety(
    paragraphs: list[str],
    article_index: int,
    article_title: str,
    opening_counts: dict[str, int],
) -> list[str]:
    """Final pass to prevent repeated paragraph openings across a generated batch."""
    varied: list[str] = []
    title_hint = re.sub(r"[，。！？；：、,.!?;:\s]+", "", article_title)[:8] or "这类项目"
    leads = [
        f"从{title_hint}看，",
        f"围绕{title_hint}，",
        f"拿{title_hint}来算，",
        f"回到{title_hint}本身，",
        f"企业看{title_hint}，",
        f"如果盯住{title_hint}，",
        f"把{title_hint}放进预算表，",
        f"换到{title_hint}的场景，",
        f"想借{title_hint}拿补贴，",
        f"别让{title_hint}只停在文件里，",
    ]
    for idx, paragraph in enumerate(paragraphs):
        text = paragraph.strip()
        if idx == len(paragraphs) - 1 or len(text) < 20:
            varied.append(text)
            continue
        key = opening_key(text)
        opening_counts[key] = opening_counts.get(key, 0) + 1
        if opening_counts[key] > 1:
            changed = True
            while changed:
                changed = False
                for existing_lead in [*leads, *OPENING_MOODS]:
                    if text.startswith(existing_lead):
                        text = text[len(existing_lead):].lstrip("，,。；;：: ")
                        changed = True
                        break
            text = remove_template_section_labels(text)
            lead_options = [
                "这一步建议先判断匹配度，",
                "企业可以换个角度理解，",
                "企业更需要看清自身基础，",
                "准备时先抓重点，",
                "深圳金赋建议先核对，",
                "这项工作适合先排一张清单，",
                "申报前把口径理顺会更稳，",
                "内部协同时可以先明确，",
                "窗口期前最好先确认，",
                "从补贴平台的匹配结果看，",
            ]
            lead = lead_options[(article_index + idx) % len(lead_options)]
            text = f"{lead}{text}"
        text = remove_template_section_labels(text)
        varied.append(remove_unbalanced_brackets(cleanup_generated_wording(text)).strip())
    return varied

def remove_template_section_labels(text: str) -> str:
    """Remove repeated handcrafted section labels from generated article paragraphs."""
    labels = [
        "先看对象", "为什么值得做", "时间和场景要抓住", "深圳金赋可以怎么帮", "材料不用一口气做完", "最后动作",
        "项目边界也要提前排除", "费用和翻译是海外项目的关键",
    ]
    cleaned = text
    for label in labels:
        cleaned = cleaned.replace(f"{label}。", "")
    return cleaned.lstrip("，,。；;：: ")


def normalize_article_title(title: str, fallback: str = "企业补贴机会，先做评估") -> str:
    cleaned = remove_old_title_years(title)
    if not cleaned:
        cleaned = remove_old_title_years(fallback) or "企业补贴机会，先做评估"
    cleaned = re.sub(r"\s+", "", cleaned).strip(" ，,、：:；;-—_（）()[]【】")
    cleaned = remove_unbalanced_brackets(cleaned[:TITLE_MAX_CHARS]).strip(" ，,、：:；;-—_（）()[]【】")
    if len(cleaned) < TITLE_MIN_CHARS:
        suffixes = ["补贴机会先评估", "专项资金先测算", "企业申报先体检", "材料口径先核清"]
        for suffix in suffixes:
            candidate = remove_unbalanced_brackets((cleaned + suffix)[:TITLE_MAX_CHARS]).strip(" ，,、：:；;-—_（）()[]【】")
            if len(candidate) >= TITLE_MIN_CHARS:
                cleaned = candidate
                break
    return cleaned or "企业补贴机会先评估"


