    proof_lines = [
        f"资料准备上，建议先建一张‘标准成果台账’：标准名称、标准层级、企业角色、发布时间、排名位置、证明材料、费用凭证、应用成效、是否拿过财政资金，都放在一张表里。补贴平台做匹配时，就能快速看出优先级。",
        f"如果企业手上有多个标准成果，别一股脑全冲。可以先按金额空间、材料完整度、时间节点、重复资助风险排队。金额高但材料弱的项目先培育，金额适中但证据齐的项目先申报，这样更现实。",
        f"尤其要注意重复申报和系列标准。政策明确已获得市级财政资金支持开展的，不得重复申请；同一个标准拆成系列发布的，还可能涉及资助金额平均分配。这个口径不先核清，后面容易返工。",
        f"标准项目跨部门很常见：技术部门掌握文本，质量部门掌握认证，行政部门保存活动资料，财务部门拿着发票和付款记录。深圳金赋会建议企业先把这些资料合到一起，不要等窗口开了再临时追。",
    ]
    business_lines = [
        f"这也是深圳金赋想帮企业做的事：把标准、认证、培训、活动、人才奖励等零散线索放进补贴平台，先生成一份更贴合企业自身的补贴清单，再判断是否需要材料补强、申报辅导或后续培育。",
        f"对企业客户来说，最有价值的不是多看几条政策，而是知道自己哪一条最可能获得补贴。深圳金赋会把政策金额、申报门槛、资料缺口和办理节奏一起梳理，让企业少做无效准备。",
        f"标准化工作本来就能提升客户信任、投标竞争力和行业影响力。如果再把补贴政策用起来，企业就不只是‘做过标准’，而是把标准成果转成了经营层面的收益。",
        f"补贴平台会把企业资料拆成可匹配字段：有没有标准文本、有没有证书、有没有活动验收、有没有审计报告、有没有采用证明。字段越完整，匹配结果越清楚。",
    ]
    service_lines = [
        f"深圳金赋的服务不止是提醒企业‘有政策’，还会结合企业行业、标准成果、财务票据、认证证书和历史申报记录，判断这项补贴是马上申、继续培育，还是先放进下一轮储备。",
        f"补贴平台适合先做一次轻量体检：企业把已有标准成果录入后，可以看到可能匹配的项目类别、金额区间、资料缺口和优先级，避免一上来就花大量时间写材料。",
        f"如果企业标准成果比较多，深圳金赋会建议先做分层：金额高且资料齐的优先推进，金额高但证据弱的重点补材料，金额小但容易拿的可以作为快速项目处理。",
        f"对没有专职政策团队的企业来说，补贴平台能把政策条款翻译成可执行动作：哪些材料找技术部门，哪些材料找财务，哪些证明要提前向合作方或协会补齐。",
    ]
    closing_lines = [
        f"如果企业已经做过{primary[0]}，可以关注「金赋补贴宝」，进入补贴平台先做一次资质评估。把标准文本、证书、公告、活动记录和费用证明放进清单里，让深圳金赋帮你看看金额空间和资料缺口，别让标准成果只停在文件夹里。",
        f"想知道{primary[0]}能不能申，建议先关注「金赋补贴宝」，进入补贴平台做政策匹配。企业不需要一开始就把所有资料写成申报书，先看条件是否对得上、金额是否值得做、资料是否还缺，决策会轻松很多。",
        f"如果你们公司标准成果不少，却一直没人系统盘点，可关注「金赋补贴宝」进入补贴平台，把标准、认证、培训、活动和人才资料先做一次体检。能申的尽快推进，暂时不成熟的也能纳入下一轮培育。",
        f"标准化投入已经发生了，就别让补贴机会擦肩而过。关注「金赋补贴宝」，进入补贴平台做企业资质评估和政策匹配，深圳金赋会帮企业把资金机会、资料短板和申报节奏看得更清楚。",
        f"如果你身边也有企业做过{primary[0]}，欢迎点赞或评论区留言行业和项目情况。深圳金赋会继续把复杂政策讲得更直观，方便企业先判断值不值得申、从哪里开始准备。",
        f"觉得这篇对{primary[0]}有帮助，可以点个赞，也欢迎在评论区说说企业已经做过哪些标准成果。深圳金赋后续会继续拆解更多深圳补贴政策，让经营者少走弯路。",
        f"还不确定{primary[0]}是否适合自己公司，欢迎评论区留下企业类型或标准成果方向。深圳金赋会围绕常见行业继续做通俗解读，帮助企业把补贴机会看得更清楚。",
        f"这篇可以先收藏，也欢迎点赞告诉我们你更想看哪类标准补贴。深圳金赋会持续整理企业看得懂、用得上的政策内容，让标准成果不再只是档案里的文件。",
    ]
    # Seven longer paragraphs: fewer blocks, richer content, and concrete
    # project-tied starts. The first sentence of every paragraph uses the
    # current project category so batch articles do not share identical leads.
    starts = [
        hooks[(variant - 1) % len(hooks)],
        f"{primary[0]}已经进入申报窗口，时间是2026年6月12日9:00—7月13日18:00，受理机关：深圳市市场监督管理局。{scenarios[0]}",
        f"{primary[0]}真正要抓住的是成果价值，{proof_lines[(variant + 2) % len(proof_lines)]}",
        f"深圳金赋看{primary[0]}，更关注企业已经做过什么、还能匹配什么。{company_lines[(variant - 1) % len(company_lines)]}{service_lines[(variant + 1) % len(service_lines)]}",
        f"再顺手排查{secondary[0]}，除了{primary[0]}，{secondary[0]}也可能有空间，政策对应的是{secondary[1]}。不一定非要冲金额最高的一项，资料成熟度高的项目反而更适合推进。",
        f"落到经营上，{primary[0]}不是孤立动作，{business_lines[(variant + 1) % len(business_lines)]}",
        f"最后给做{primary[0]}的企业一个提醒，{closing_lines[(variant - 1) % len(closing_lines)]}",
    ]
    paragraph_tails = [
        f"一句话，{primary[0]}不是单纯的专业标签，它可能是企业拿补贴、拿奖励、做品牌背书的共同入口。",
        f"比如{tertiary[0]}，政策对应的是{tertiary[1]}，这个方向不一定最显眼，却适合资料比较扎实的企业做补充匹配。",
        f"别小看采用证明、推广报告和现场记录，这些材料往往能把‘做过’变成‘做成了’，也更容易说明经济效益或社会效益。",
        f"尤其是中小企业，平时没有专人盯政策，更需要把标准成果先放进一套可复用的资料库，后续申报其他项目也能接着用。",
        f"标准专项资金的机会不止一条，主导制定、参与制定、获证、培优、活动、培训、人才奖励都要分开看，别把所有成果挤进同一个口径。",
        f"企业真正要做的，是把已经发生的标准化投入变成能被政策识别的证据链：谁参与、做了什么、产生了多少支出、带来什么效果。",
        f"先评估，再取舍，再推进，这比临时抱佛脚更省心，也更符合企业做补贴规划的节奏。",
    ]
    paragraphs = [
        f"{starts[i]}{paragraph_tails[(variant + i) % len(paragraph_tails)]}" for i in range(7)
    ]
    # If an article is short because the selected phrases are compact, expand
    # existing paragraphs instead of adding many small blocks. This keeps the
    # article at 6-9 paragraphs as requested.
    expanders = [
        f"再往细处看，{primary[2]}这些资料最好不要只在申报时才整理，平时就按项目名称和年度归档，后面无论申报标准资金还是其他产业扶持，都能直接复用。",
        f"另外，{secondary[0]}也建议一并排查，{secondary[2]}如果已经具备，可以作为同一轮补贴体检里的备选项目，避免企业只盯一个入口而漏掉更容易落地的机会。",
        f"对管理层来说，这类政策的价值不只是拿一笔资金，更是倒逼企业把研发、质量、标准、市场和财务资料打通，形成以后可持续申报的资料底座。",
        f"对经办团队来说，提前核对排名、有效期、采用证明、费用口径和是否重复资助，比后期反复补材料更省时间，也能减少申报风险。",
        f"如果企业已经有标准化基础，建议把这项资金放进年度补贴规划，而不是等通知临近才想起来。补贴平台可以先帮企业做匹配，判断先冲哪类、培育哪类、放弃哪类。",
    ]
    idx = 0
    while sum(len(p) for p in paragraphs) < MIN_ARTICLE_CHARS + 80:
        target = 1 + (idx % 5)
        paragraphs[target] = f"{paragraphs[target]}{expanders[idx % len(expanders)]}"
        idx += 1
    return {
        "title": "2026年度深圳标准领域专项资金资助奖励项目申报指南",
        "source": source,
        "valid_period": "2026年6月12日9:00—7月13日18:00",
        "max_amount": "国际标准最高100万元；国际标准化人才最高200万元；标准试点示范最高50万元；深圳标准认证单项最高10万元",
        "from_url": url,
        "article_title": remove_unbalanced_brackets(article_title),
        "paragraphs": [remove_unbalanced_brackets(cleanup_generated_wording(p)).strip() for p in paragraphs],
        "skip_polish": True,
    }

