    used_expanders: set[str] = set()
    expand_index = 0
    while sum(len(p) for p in paragraphs) < max(MIN_ARTICLE_CHARS, 1000) and expand_index < len(expanders) * 3:
        expander = expanders[(idx + expand_index) % len(expanders)]
        if expander not in used_expanders and expander not in "".join(paragraphs):
            target = 2 + ((idx + expand_index) % 5)
            paragraphs[target] += expander
            used_expanders.add(expander)
        expand_index += 1
    if sum(len(p) for p in paragraphs) < 1200:
        paragraphs[6] += "深圳金赋还会把企业资质、研发投入、知识产权、产学研合作和后续政策机会连起来看，让项目不只是一次申报，而是能沉淀为长期政策资产。团队后续做科技成果转化、研发资助或人才项目时，这份项目画像也能继续复用。对企业来说，这不是把政策讲得更复杂，而是把该不该做、谁来做、怎么继续做提前说清楚。尤其是已有研发投入、医疗卫生合作、农业食品场景或装备验证基础的团队，越早把项目主线整理出来，越容易在申报窗口打开时快速进入状态。"
    return {
        "title": "2026年度广东省基础与应用基础研究基金江门市联合基金（粤江联合基金）项目申报指南",
        "source": source,
        "valid_period": "申报时间以省基金项目申报通知及系统开放安排为准",
        "max_amount": "青年基金10万元/项，地区培育30万元/项，重点项目100万元/项",
        "from_url": url,
        "article_title": remove_unbalanced_brackets(article_title),
        "paragraphs": [remove_unbalanced_brackets(cleanup_generated_wording(p)).strip() for p in paragraphs],
        "skip_polish": True,
        "skip_opening_variation": True,
    }

