        "惠州的产业题目不缺，缺的是把产业问题提炼成科研问题的那一步。",
        "即使团队缺少完整申报经验，深圳金赋也可以从项目盘点切入，把成熟方向和培育方向分开管理。",
        "项目越早做体检，越容易发现负责人、合作单位、成果基础和研究方向之间的错位。",
