    expand_index = 0
    used_expanders: set[str] = set()
    while sum(len(p) for p in paragraphs) < MIN_ARTICLE_CHARS and expand_index < len(expanders) * 3:
        expander = expanders[(idx + expand_index) % len(expanders)]
        if expander not in used_expanders and expander not in "".join(paragraphs):
            target = 2 + ((idx + expand_index) % 5)
            paragraphs[target] += expander
            used_expanders.add(expander)
        expand_index += 1
    return {
        "title": "2026年度广东省基础与应用基础研究基金广州市联合基金（粤穗联合基金）项目申报指南",
        "source": source,
        "valid_period": "申报时间以省基金项目申报通知及系统开放安排为准",
        "max_amount": "青年基金10万元/项，地区培育30万元/项，重点项目100万元/项，粤港澳研究团队200万元/项",
        "from_url": url,
        "article_title": remove_unbalanced_brackets(article_title),
        "paragraphs": [remove_unbalanced_brackets(cleanup_generated_wording(p)).strip() for p in paragraphs],
        "skip_polish": True,
        "skip_opening_variation": True,
    }

