        f"对于外资企业，深圳金赋会更关注长期规划：这次外资奖励能不能测，后续研发、设备、人才、贴息、知识产权政策能不能接上，尽量让一次梳理服务多轮政策窗口。",
        f"补贴平台的用法很简单，录入企业基础信息和外资相关情况后，就能看到系统匹配出的政策方向。{label}不用一开始就准备大堆说明，把机会大小测出来更实际。",
