            caution_lines[(variant + 3) % len(caution_lines)],
            f"从深圳金赋补贴平台视角看，{label}不只是一次奖励申报，更是企业把外资到账、区域布局和后续补贴机会重新盘清楚的入口。先测算、再规划，企业会更容易把握节奏。",
