        "对企业来说，这类项目能把平时分散在法务、技术、品牌和财务里的资料重新串起来，形成可沉淀、可复用的知识产权资产。",
        "如果研究成果能服务深圳产业、新兴技术或企业出海，它就不只是内部总结，而可能成为对行业有参考价值的项目。",
